class BinaryWriter:

    def __init__(self, cache_dir: str, distributed_env: Optional[str] = None):
        self._cache_dir = cache_dir
        self._distributed_env = distributed_env

    def rank(self) -> int:
        """Returns the rank of the writer."""

    def _merge_no_wait(self, node_rank: Optional[int] = None) -> None:
        """Once all the workers have written their own index, the merge function is responsible to read and merge them
        into a single index."""

    def merge(self, num_workers: int = 1, node_rank: Optional[int] = None) -> None:

        if self._distributed_env is not None:
            if node_rank == 0:
                # Wait for all index files to become available
                expected_files = [f"index_{i}.bin" for i in range(num_workers)]
                while not all(os.path.isfile(os.path.join(self._cache_dir, file)) for file in expected_files):
                    time.sleep(1)
                # Merge the index files
                self._merge_no_wait(node_rank)
            else:
                # Wait for the merged index file to become available
                while not os.path.isfile(os.path.join(self._cache_dir, litdata.constants._INDEX_FILENAME)):
                    time.sleep(1)
        else:
            # We're not in a distributed environment, so just merge the index files
            self._merge_no_wait(node_rank)
