import geopoly
import numpy as np

def generate_basis(
    base_shape, angular_tesselation, remove_symmetries=True, eps=1e-4
):

  # Tessellate the base shape
  vertices = geopoly.tesselate_geodesic(base_shape, angular_tesselation)

  # Compute the centroid of the vertices
  centroid = np.mean(vertices, axis=0)

  # Calculate the squared distances between all pairs of vertices
  squared_distances = np.zeros((len(vertices), len(vertices)))
  for i in range(len(vertices)):
      for j in range(i+1, len(vertices)):
          squared_distances[i, j] = geopoly.compute_sq_dist(vertices[i], vertices[j])
          squared_distances[j, i] = squared_distances[i, j]

  # Set the squared distance threshold
  squared_distance_threshold = eps**2

  # Find pairs of symmetric vertices and remove one of them
  if remove_symmetries:
      for i in range(len(vertices)):
          for j in range(i+1, len(vertices)):
              if squared_distances[i, j] < squared_distance_threshold:
                  if np.linalg.norm(np.dot(vertices[i] - centroid, np.array([0, 1, 0])) - np.dot(vertices[j] - centroid, np.array([0, 1, 0]))) < eps:
                      vertices = np.delete(vertices, j, axis=0)
                      squared_distances = np.delete(squared_distances, j, axis=0)
                      squared_distances = np.delete(squared_distances, j, axis=1)
                      break

  return vertices
