    """
    # Subtract half of each element in the array bitwise ANDed with the s55 mask
    for i in range(len(arr)) :
        arr[i] = (arr[i] >> 1) - (arr[i] & s55 >> 1)
    # Apply the s33 mask to the array and add it to itself right-shifted by 2 bits ANDed with the same mask
    for i in range(len(arr)) :
        arr[i] = (arr[i] & s33) + ((arr[i] >> 2) & s33)
